insert into public.posts (id, author_id, place_id, kind, display_time, text, tags, likes_count, image_url, sort_order, moderation_status)
values
  ('post-1', 'nikos', 'kourouta-beach', 'spot', '18 min ago', 'Kourouta is filling up already. Music starts after sunset. Don''t come too late if you want parking.', array['beach', 'tonight', 'parking']::text[], 48, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/%CE%9A%CE%BF%CF%85%CF%81%CE%BF%CF%8D%CF%84%CE%B1_-_panoramio_%281%29.jpg/1280px-%CE%9A%CE%BF%CF%85%CF%81%CE%BF%CF%8D%CF%84%CE%B1_-_panoramio_%281%29.jpg', 0, 'published'),
  ('post-2', 'maria', 'zacharo-beach', 'photo', '32 min ago', 'Zacharo sunset is insane and way less packed than expected.', array['sunset', 'quiet', 'cheap']::text[], 31, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/500px_photo_%28255278229%29.jpeg/1280px-500px_photo_%28255278229%29.jpeg', 1, 'published'),
  ('post-3', 'nikos', 'amaliada-square', 'tip', '1h ago', 'Pregame in Amaliada then Kourouta. Classic summer move.', array['pregame', 'local', 'after']::text[], 64, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/%CE%A0%CE%BB%CE%B1%CF%84%CE%B5%CE%AF%CE%B1_%CE%91%CE%BC%CE%B1%CE%BB%CE%B9%CE%AC%CE%B4%CE%B1.jpg/1280px-%CE%A0%CE%BB%CE%B1%CF%84%CE%B5%CE%AF%CE%B1_%CE%91%CE%BC%CE%B1%CE%BB%CE%B9%CE%AC%CE%B4%CE%B1.jpg', 2, 'published'),
  ('post-4', 'eleni', 'pyrgos-night', 'event', 'tonight', 'Small DJ thing near the old Rex corner. Starts late, obviously.', array['dj', 'night', 'local']::text[], 22, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/%CE%9A%CE%B9%CE%BD%CE%B7%CE%BC%CE%B1%CF%84%CE%BF%CE%B3%CF%81%CE%AC%CF%86%CE%BF%CF%82_%C2%AB%CE%A1%CE%AD%CE%BE%C2%BB.jpg/1280px-%CE%9A%CE%B9%CE%BD%CE%B7%CE%BC%CE%B1%CF%84%CE%BF%CE%B3%CF%81%CE%AC%CF%86%CE%BF%CF%82_%C2%AB%CE%A1%CE%AD%CE%BE%C2%BB.jpg', 3, 'published'),
  ('post-5', 'nikos', 'foloi-forest', 'tip', 'today', 'Foloi is perfect right now. Shade, quiet, no beach chaos. Bring water and don''t leave trash.', array['nature', 'respect', 'walk']::text[], 57, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Foloi_Forest_-_panoramio.jpg/1280px-Foloi_Forest_-_panoramio.jpg', 4, 'published'),
  ('post-6', 'andreas', 'agios-andreas', 'spot', '2h ago', 'Fresh fish tonight, tables outside, sunset view. No dress code nonsense.', array['food', 'sunset', 'sea']::text[], 19, 'https://upload.wikimedia.org/wikipedia/commons/8/81/Sunset_at_Agios_Andreas.jpg', 5, 'published'),
  ('post-7', 'maria', 'katakolo-port', 'photo', '45 min ago', 'Katakolo is touristy but the port walk is actually nice at golden hour.', array['port', 'walk', 'photo']::text[], 27, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Katakolo_Port.jpg/1280px-Katakolo_Port.jpg', 6, 'published'),
  ('post-8', 'nikos', 'andritsaina', 'tip', 'tonight', 'Village night up here. Slow food, cold beers, better temperature than the coast.', array['village', 'beer', 'slow']::text[], 39, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Andritsaina_overview.jpg/1280px-Andritsaina_overview.jpg', 7, 'published')
