insert into public.route_stops (route_id, position, display_time, place_id, title, body)
values
  ('route-1', 0, '17:30', 'kourouta-beach', 'Arrive late', 'Swim, chill, don''t roast in the midday heat.'),
  ('route-1', 1, '21:30', 'amaliada-square', 'Pregame in the square', 'Cheap food and pregame. More local than beach bar prices.'),
  ('route-1', 2, '23:45', 'kourouta-sunset', 'Back to Kourouta', 'Follow the music. Don''t overplan.'),
  ('route-2', 0, '10:00', 'katakolo-port', 'Port walk', 'Coffee, sea air, watch the cruise ships dock.'),
  ('route-2', 1, '12:15', 'katakolo-kiani-akti', 'Quick swim', 'Small beach reset close enough to walk without turning the day into logistics.'),
  ('route-2', 2, '19:00', 'agios-andreas', 'Seafood + drinks', 'Tables outside, sunset, no dress code.'),
  ('route-3', 0, '17:00', 'zacharo-beach', 'Wide sand', 'Big sky, fewer people, free vibes.'),
  ('route-3', 1, '14:00', 'kakovatos-beach', 'Low-key swim', 'Skip the obvious scene. Endless beach.'),
  ('route-3', 2, '19:30', 'giannitsochori', 'South coast sunset', 'Remote-ish. Worth the drive.'),
  ('route-4', 0, '09:00', 'foloi-forest', 'Forest walk', 'Shade, quiet, no beach chaos. Bring water.'),
  ('route-4', 1, '12:00', 'foloi-deep', 'Go deeper', 'For the alternative/nature people. Leave no trash.'),
  ('route-4', 2, '19:00', 'andritsaina', 'Mountain village night', 'Slow food, cold beers, better temperature.'),
  ('route-5', 0, '10:00', 'ancient-olympia', 'Olympia at golden hour', 'Ancient ruins, surprisingly walkable.'),
  ('route-5', 1, '14:00', 'ancient-elis', 'Hidden ruins', 'Calm archaeology, no tourist pressure.'),
  ('route-5', 2, '18:30', 'chlemoutsi', 'Castle sunset', 'Hill view, Ionian horizon, photos.')
on conflict (route_id, position) do update set
    display_time = excluded.display_time,
    place_id = excluded.place_id,
    title = excluded.title,
    body = excluded.body;

